def _moc_moi(cac_tin, cac_phong_cu, khach_id, *, ben_khach):
    """Mốc đã đọc sau khi gộp: ngay trước tin chưa đọc sớm nhất của mọi phòng cũ.

    Phía khách chưa đọc tin của nhà thuốc; phía nhà thuốc chưa đọc tin của khách.
    """
    cot_moc = "tin_khach_da_doc_id" if ben_khach else "tin_nha_thuoc_da_doc_id"
    chua_doc = [
        tin.pk
        for tin in cac_tin
        if (tin.nguoi_gui_id != khach_id) == ben_khach
        and tin.pk > (cac_phong_cu[tin.id_phong_cu][cot_moc] or 0)
    ]
    if not chua_doc:
        cac_moc = [phong[cot_moc] for phong in cac_phong_cu.values() if phong[cot_moc]]
        return max(cac_moc) if cac_moc else None
    truoc = [tin.pk for tin in cac_tin if tin.pk < min(chua_doc)]
    return max(truoc) if truoc else None


def gop_cuoc_tro_chuyen(apps, schema_editor):
    """Mỗi khách chỉ còn một cuộc trò chuyện với mỗi chi nhánh (kiểu Shopee).

    Phòng "về đơn" cũ được nhập vào phòng chung; tin đầu của phòng đó gắn thẻ đơn hàng để
    vẫn thấy khách đã hỏi về đơn nào. Mốc đã đọc lấy tin chưa đọc sớm nhất nên không tin
    chưa đọc nào bị coi là đã đọc.
    """
    from django.db.models import Count, Max, Min

    CuocTroChuyen = apps.get_model("tro_chuyen", "CuocTroChuyen")
    TinNhan = apps.get_model("tro_chuyen", "TinNhan")
    cac_nhom = (
        CuocTroChuyen.objects.values("khach_hang_id", "chi_nhanh_id")
        .annotate(so=Count("pk"), co_don=Count("don_hang"))
        .filter(co_don__gt=0)
    )
    for nhom in cac_nhom:
        cac_phong = list(
            CuocTroChuyen.objects.filter(
                khach_hang_id=nhom["khach_hang_id"], chi_nhanh_id=nhom["chi_nhanh_id"]
            ).order_by("pk")
        )
        giu = next((p for p in cac_phong if p.don_hang_id is None), cac_phong[0])
        cu = {
            p.pk: {
                "tin_khach_da_doc_id": p.tin_khach_da_doc_id,
                "tin_nha_thuoc_da_doc_id": p.tin_nha_thuoc_da_doc_id,
            }
            for p in cac_phong
        }
        cac_tin = []
        for phong in cac_phong:
            tin_cua_phong = list(TinNhan.objects.filter(cuoc_tro_chuyen=phong).order_by("pk"))
            if phong.don_hang_id and tin_cua_phong:
                TinNhan.objects.filter(pk=tin_cua_phong[0].pk).update(don_hang_id=phong.don_hang_id)
            for tin in tin_cua_phong:
                tin.id_phong_cu = phong.pk
            cac_tin += tin_cua_phong
        cac_tin.sort(key=lambda tin: tin.pk)
        khach = nhom["khach_hang_id"]
        moc_khach = _moc_moi(cac_tin, cu, khach, ben_khach=True)
        moc_nha_thuoc = _moc_moi(cac_tin, cu, khach, ben_khach=False)
        khac = [p.pk for p in cac_phong if p.pk != giu.pk]
        TinNhan.objects.filter(cuoc_tro_chuyen_id__in=khac).update(cuoc_tro_chuyen_id=giu.pk)
        dang_mo = any(p.trang_thai_xu_ly == "dang_mo" for p in cac_phong)
        xong_cuoi = max(
            (p for p in cac_phong if p.thoi_diem_xong), key=lambda p: p.thoi_diem_xong, default=None
        )
        tong_hop = TinNhan.objects.filter(cuoc_tro_chuyen_id=giu.pk).aggregate(cuoi=Max("pk"))
        tao_som = CuocTroChuyen.objects.filter(pk__in=[p.pk for p in cac_phong]).aggregate(
            som=Min("thoi_diem_tao")
        )
        CuocTroChuyen.objects.filter(pk__in=khac).delete()
        CuocTroChuyen.objects.filter(pk=giu.pk).update(
            loai_cuoc_tro_chuyen="tu_van",
            don_hang_id=None,
            tin_cuoi_id=tong_hop["cuoi"],
            tin_khach_da_doc_id=moc_khach,
            tin_nha_thuoc_da_doc_id=moc_nha_thuoc,
            trang_thai_xu_ly="dang_mo" if dang_mo or xong_cuoi is None else "da_xong",
            thoi_diem_xong=None if dang_mo or xong_cuoi is None else xong_cuoi.thoi_diem_xong,
            nguoi_danh_dau_xong_id=(
                None if dang_mo or xong_cuoi is None else xong_cuoi.nguoi_danh_dau_xong_id
            ),
            thoi_diem_tao=tao_som["som"],
        )


